<script setup>
import { computed, inject, nextTick, onBeforeUnmount, reactive, ref, watch } from 'vue'
import AppIcon from '../components/AppIcon.vue'
import { agentQuestions, appOptions, getMockFiles } from '../ui/mock-data.js'
import { uiContextKey } from '../ui/context.js'
import { formatBytes } from '../top50.js'
const { previewAppId }=inject(uiContextKey,{previewAppId:ref('10350')})
const draft=ref(''),pending=ref(false),composer=ref(null),messageList=ref(null)
const conversations=reactive({'10350':[],'10066':[]})
const messages=computed(()=>conversations[previewAppId.value])
const sampleFiles=computed(()=>getMockFiles(previewAppId.value).slice(0,3))
let timer
watch(previewAppId,()=>{draft.value=''})
function choose(question){draft.value=question;nextTick(()=>composer.value?.focus())}
async function scrollToEnd(){await nextTick();if(messageList.value) messageList.value.scrollTop=messageList.value.scrollHeight}
function send(){
  const text=draft.value.trim()
  if(!text||pending.value) return
  const appId=previewAppId.value
  conversations[appId].push({role:'user',text})
  draft.value=''
  pending.value=true
  scrollToEnd()
  timer=setTimeout(()=>{
    conversations[appId].push({role:'assistant',text:'当前为 UI 预览，尚未连接 LLM 或实时业务工具，暂不能回答该业务问题。没有发起模型请求、执行查询或生成报告。',appId})
    pending.value=false
    scrollToEnd()
  },250)
}
onBeforeUnmount(()=>clearTimeout(timer))
</script>
<template><div data-page="agent"><header class="page-heading"><div><h1>CDN 智能运营助手</h1><p>围绕热点洞察、模型评估和压缩效果组织运营问答，业务证据接入后再提供真实分析。</p></div><span class="source-badge">UI MOCK · 未连接模型</span></header>
  <div class="agent-layout"><aside class="card agent-shortcuts"><div class="agent-context"><h2>对话上下文</h2><label for="agent-app">AppID</label><select id="agent-app" v-model="previewAppId"><option v-for="option in appOptions" :key="option.id" :value="option.id">{{ option.label }}</option></select><small>不同 App 的本页消息分别保留</small></div><div class="agent-question-heading"><AppIcon name="agent" :size="16"/><h2>你可以这样问</h2></div><div class="question-list"><button v-for="(question,index) in agentQuestions" :key="question" @click="choose(question)"><AppIcon :name="['compression','pie','backtest','money','file'][index]" :size="16"/><span>{{ question }}</span><AppIcon name="chevron" :size="12"/></button></div><div class="agent-capabilities"><span>后续接入方向</span><p><i/>热点与推荐原因</p><p><i/>压缩收益与效果</p><p><i/>模型评估与逾期查询</p><small>当前仅提供界面与交互结构</small></div></aside>
  <section class="card chat-panel" aria-label="Agent 对话"><header class="chat-heading"><span class="agent-avatar"><AppIcon name="agent" :size="24"/></span><div><h2>CDN 智能运营助手</h2><p>App {{ previewAppId }} <span>·</span> 本页交互演示</p></div><span class="connection-status"><i/>模型未接入</span></header><div ref="messageList" class="chat-messages" role="log" aria-live="polite" aria-label="对话消息"><div class="chat-date">界面预览 · 无实时业务数据</div><div class="chat-message chat-message--assistant"><span class="message-avatar"><AppIcon name="agent" :size="19"/></span><div class="message-content"><div class="message-author">运营助手 <span>界面欢迎信息</span></div><div class="message-bubble"><strong>从一个问题开始，了解你的 CDN 业务。</strong><p>选择左侧问题或输入你的问题。后续可在这里查看热点文件、模型指标与降本证据。</p><div class="welcome-topics"><span><AppIcon name="chart" :size="13"/>热点洞察</span><span><AppIcon name="compression" :size="13"/>压缩决策</span><span><AppIcon name="backtest" :size="13"/>模型比较</span></div></div></div></div>
    <section v-if="messages.length===0" class="agent-example-card"><header><span><AppIcon name="file" :size="15"/>结构化文件卡片示例</span><span class="source-badge">UI MOCK · 非真实推荐</span></header><p>以下仅展示未来消息卡片的排版，不是对业务问题的回答。</p><div class="table-scroll"><table><thead><tr><th>文件路径</th><th>预测流量（样例）</th><th>预计净收益（样例）</th></tr></thead><tbody><tr v-for="file in sampleFiles" :key="file.fileKey"><td><span class="file-key" :title="file.fileKey">{{ file.fileKey }}</span></td><td>{{ formatBytes(file.predictedBytes) }}</td><td class="text-green">¥ {{ file.uiEstimatedBenefit }}</td></tr></tbody></table></div><footer>App {{ previewAppId }} · 固定 UI 样例 · 无工具调用</footer></section>
    <div v-for="(message,index) in messages" :key="`${previewAppId}-${index}`" class="chat-message" :class="`chat-message--${message.role}`"><span class="message-avatar" :class="{'message-avatar--user':message.role==='user'}"><AppIcon v-if="message.role==='assistant'" name="agent" :size="19"/><span v-else>我</span></span><div class="message-content"><div class="message-author">{{ message.role==='user' ? '你' : '运营助手' }}<span v-if="message.role==='assistant'">未接入提示 · App {{ message.appId }}</span></div><div class="message-bubble"><p>{{ message.text }}</p></div></div></div>
    <div v-if="pending" class="chat-loading" role="status"><span class="loader"/>界面消息处理中 · 未调用模型</div>
  </div><div class="chat-compose"><form @submit.prevent="send"><label class="sr-only" for="agent-message">输入运营问题</label><textarea id="agent-message" ref="composer" v-model="draft" rows="2" maxlength="2000" placeholder="输入你的问题，例如：今天有哪些值得压缩的文件？" :disabled="pending" @keydown.enter.exact.prevent="send"/><div class="composer-footer"><span>Enter 发送，Shift + Enter 换行 <span class="composer-context">· App {{ previewAppId }}</span></span><button class="btn btn-primary" type="submit" :disabled="pending || !draft.trim()" aria-label="发送消息"><AppIcon name="send" :size="16"/><span>发送</span></button></div></form><p><AppIcon name="info" :size="12"/>当前未连接 LLM，消息仅保留在本页内存，不会执行业务操作。</p></div></section></div>
</div></template>
