-weight:600;color:#344f73;margin:0 0 5px}.chat-heading p{margin:0;font-size:10px;color:#94a5bc}.chat-heading p>span{margin:0 7px}.connection-status{margin-left:auto;font-size:10px;color:#9dacbe;display:flex;align-items:center;gap:6px}.connection-status i{width:5px;height:5px;background:#bcc8d8;border-radius:50%}.chat-messages{flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain;padding:17px 23px 24px;background:linear-gradient(180deg,#fbfdff,#fff)}.chat-date{text-align:center;color:#b4bfce;font-size:9px;margin:2px 0 25px}.chat-message{display:flex;align-items:flex-start;gap:11px;margin-bottom:21px}.message-avatar{display:grid;place-items:center;width:31px;height:31px;background:#ebf3ff;color:#428be8;border:1px solid #dfecff;border-radius:9px;flex:none;font-size:10px}.message-author{font-size:10px;color:#7a92b2;margin:1px 0 9px}.message-author>span{font-size:8px;margin-left:10px;color:#b0bdd0}.message-content{max-width:86%;min-width:0}.message-bubble{padding:16px 18px;border:1px solid #e8eef7;background:white;border-radius:0 9px 9px 9px;color:#6b83a3;font-size:12px;line-height:1.9;overflow-wrap:anywhere;box-shadow:0 2px 8px #476b9c03}.message-bubble strong{font-size:13px;font-weight:550;color:#466384}.message-bubble p{margin:0;white-space:pre-wrap}.message-bubble strong+p{margin-top:8px}.welcome-topics{display:flex;gap:9px;margin-top:15px;flex-wrap:wrap}.welcome-topics span{display:flex;align-items:center;gap:5px;background:#f2f7ff;padding:3px 8px;color:#7a9ac4;font-size:9px;border-radius:3px}.agent-example-card{margin-left:42px;max-width:690px;border:1px solid #e3ebf6;border-radius:7px;background:white;margin-bottom:20px;overflow:hidden}.agent-example-card>header{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:15px 16px 0}.agent-example-card>header>span:first-child{display:flex;align-items:center;gap:6px;color:#5a7ba4;font-size:11px}.agent-example-card>p{font-size:9px;color:#9eafc5;margin:10px 16px 14px;line-height:1.8}.agen